// taskFlowConfig configures the fake Cloud task server.
type taskFlowConfig struct {
	// actionTasks is the task ID list returned by the mutating action
	// (POST/PATCH/DELETE). nil means the default single task; a non-nil empty
	// slice emulates a no-op update where the API creates no task.
	actionTasks *[]string
	// actionFields holds more fields for the action response, next to tasks
	actionFields map[string]any
	// taskState reported for the polled task; defaults to FINISHED.
	taskState cloud.TaskState
	// taskError reported when taskState == ERROR.
	taskError string
	// resource is the body of the final resource GET. nil means the superset
	// described in newTaskFlowServer.
	resource map[string]any
	// resourceNotFound is the number of first resource GETs that return 404. A
	// negative value makes every resource GET return 404
	resourceNotFound int
	// resourceGet, if set, handles every resource GET in place of the other resource fields
	resourceGet http.HandlerFunc
	// requests, if set, records every request the server receives.
	requests *requestLog
	// taskOverrides changes the task with the given ID. Other tasks use taskState, taskError and the
	// default created resources
	taskOverrides map[string]taskOverride
}

// taskOverride changes one task of the fake task server. Zero fields keep the default values
type taskOverride struct {
	state cloud.TaskState
	err   string
	// created replaces created_resources. Use json.RawMessage("null") for a null value
	created any
}

// requestLog records requests as "METHOD /path". It is safe for concurrent use.
type requestLog struct {
	mu   sync.Mutex
	list []string
}

func (l *requestLog) add(r *http.Request) {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.list = append(l.list, r.Method+" "+r.URL.Path)
}

func (l *requestLog) all() []string {
	l.mu.Lock()
	defer l.mu.Unlock()
	return slices.Clone(l.list)
}

// newTaskFlowServer returns an httptest.Server emulating the Cloud async flow:
//   - a mutating request (the action) returns a TaskIDList
//   - GET .../tasks/{id} returns a task in the configured state, with every
//     created_resources field populated so any *AndPoll method finds its resource
//   - any other GET (the final resource fetch) returns an empty JSON object, or
//     404 for the first cfg.resourceNotFound requests
func newTaskFlowServer(cfg taskFlowConfig) *httptest.Server {
	tasks := []string{"task-1"}
	if cfg.actionTasks != nil {
		tasks = *cfg.actionTasks
	}
	state := cfg.taskState
	if state == "" {
		state = cloud.TaskStateFinished
	}
	created := map[string]any{"projects": []int64{1}, "ddos_profiles": []int64{1}}
	for _, f := range createdResourceStringFields {
		created[f] = []string{andPollCreatedID}
	}

	// task mirrors the shape of a real GET /v1/tasks/{id} response (captured from
	// the Cloud API — a FINISHED create_fip task), so the custom parsing code is
	// exercised against a realistic payload. state/error/created_resources are
	// overridden per test; created_resources is a superset carrying one ID under
	// every field so any NewAndPoll method finds its resource.
	var errVal any
	if cfg.taskError != "" {
		errVal = cfg.taskError
	}
	task := map[string]any{
		"id":                  "50e2042d-761b-4f5a-b5bf-e11031c747b0",
		"state":               state,
		"task_type":           "create_fip",
		"client_id":           3621,
		"user_id":             4585,
		"user_client_id":      3621,
		"project_id":          379987,
		"region_id":           76,
		"detailed_state":      nil,
		"request_id":          "01601532933a3a7e7a71f935befd1dd1",
		"error":               errVal,
		"created_on":          "2026-07-01T13:37:14",
		"updated_on":          "2026-07-01T13:37:17",
		"finished_on":         "2026-07-01T13:37:17",
		"acknowledged_at":     nil,
		"acknowledged_by":     nil,
		"job_id":              nil,
		"schedule_id":         nil,
		"lifecycle_policy_id": nil,
		"created_resources":   created,
	}

	var resourceGets atomic.Int64
	return httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if cfg.requests != nil {
			cfg.requests.add(r)
		}
		w.Header().Set("Content-Type", "application/json")
		switch {
		case r.Method == http.MethodGet && strings.Contains(r.URL.Path, "/tasks/"):
			body := task
			if override, ok := cfg.taskOverrides[path.Base(r.URL.Path)]; ok {
				body = maps.Clone(task)
				if override.state != "" {
					body["state"] = override.state
				}
				if override.err != "" {
					body["error"] = override.err
				}
				if override.created != nil {
					body["created_resources"] = override.created
				}
			}
			_ = json.NewEncoder(w).Encode(body)
		case r.Method == http.MethodGet && cfg.resourceGet != nil:
			cfg.resourceGet(w, r)
		case r.Method == http.MethodGet && (cfg.resourceNotFound < 0 || resourceGets.Add(1) <= int64(cfg.resourceNotFound)):
			w.WriteHeader(http.StatusNotFound)
			_ = json.NewEncoder(w).Encode(map[string]any{"message": "not found"})
		case r.Method == http.MethodGet && cfg.resource != nil:
			_ = json.NewEncoder(w).Encode(cfg.resource)
		case r.Method == http.MethodGet:
			// The final resource fetch (or List). Most *AndPoll methods return this
			// value unmodified, so an empty object suffices; but a few re-fetch the
			// parent and search a nested collection for the just-created child
			// (BaremetalRegionalServer via List.results, SecurityGroupRule via
			// sg.security_group_rules), and
			// InstanceImage.UploadAndPoll polls the image until it reports
			// status "active" with a non-zero size. The superset below carries the
			// created ID in each of those collections plus a settled image state so
			// the lookups succeed; unrelated resource types ignore the extra fields.
			_ = json.NewEncoder(w).Encode(map[string]any{
				"count":                1,
				"results":              []map[string]any{{"id": andPollCreatedID}},
				"members":              []map[string]any{{"id": andPollCreatedID}},
				"security_group_rules": []map[string]any{{"id": andPollCreatedID}},
				"status":               "active",
				"size":                 1,
			})
		default: // the action: New/Update/Delete/Resize/Action/...
			body := map[string]any{"tasks": tasks}
			maps.Copy(body, cfg.actionFields)
			_ = json.NewEncoder(w).Encode(body)
		}
	}))
}

